#define KELLY_DECOMP_FULL_FEMULTI_MENU
#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/FEMenu_shared.h"
#undef KELLY_DECOMP_FULL_FEMENU_ENTRY
#undef KELLY_DECOMP_FULL_FEMULTI_MENU

struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class HelpbarFE {
    enum { ARROW_H, ARROW_V, ARROW_BOTH };
    void ChangeBtn(int index, bool add, stringx text);
public:
    void Reset();
    void AddArrowH(stringx text=stringx("")) { ChangeBtn(ARROW_H, true, text); ChangeBtn(ARROW_BOTH, false, ""); }
    void AddArrowV(stringx text=stringx("")) { ChangeBtn(ARROW_V, true, text); ChangeBtn(ARROW_BOTH, false, ""); }
    void Reformat();
};

class FEManager {
    char padding[0x156a4];
public:
    HelpbarFE *helpbar;
};

class SaveLoadFrontEnd {
    char padding0[0x329c];
public:
    int cur_type;
    char padding1[0x32b4 - 0x32a0];
    bool in_frontend;
    enum { SL_SAVE = 0 };
};

class NamesMenu : public FEMultiMenu {
    int type;
    bool save;
    char padding0[0x170 - 0x165];
    SaveLoadFrontEnd *sl_parent;
    char padding1[0x1bc - 0x174];
    MemCard cards[2];
    stringx blank_name;
    int active_card;
    int adjusted_active_card;
    bool cardSide;
    char padding2[0x20c - 0x205];
    PanelQuad *box;
    PanelQuad *arrows[2][2];
    PanelQuad *lines[10], *top_line, *side_line;
    FEMenuEntry *entry[17];
    void *message;
    void *freeSpace;
    bool draw_message;
public:
    void OnActivate();
    void TurnPQ(bool);
    static int FindAdjusted(int);
    static int FindActive(int);
    void SetSecondaryCursor(FEMenuEntry *);
private:
    void GetFileList(int, int);
    void CheckCardNum(int);
    void SetActiveCard();
    void UpdateMessage();
    void OnCardSwitch();
};

extern FEManager frontendmanager;
extern stringx ksGlobalTextArray[];
enum { LOWEST_CARD = 0, HIGHEST_CARD = 2, GT_FE_MENU_SWITCH = 143 };

__asm__(".equ frontendmanager, 0x003F7728");
__asm__(".equ ksGlobalTextArray, 0x003E6050");
__asm__(".equ TurnPQ__9NamesMenub, 0x0019EC78");
__asm__(".equ FindAdjusted__9NamesMenui, 0x001A0808");
__asm__(".equ FindActive__9NamesMenui, 0x001A0810");
__asm__(".equ SetSecondaryCursor__9NamesMenuP11FEMenuEntry, 0x001A0818");
__asm__(".equ GetFileList__9NamesMenuii, 0x0019FFA8");
__asm__(".equ CheckCardNum__9NamesMenui, 0x001A0470");
__asm__(".equ SetActiveCard__9NamesMenu, 0x0019FD40");
__asm__(".equ UpdateMessage__9NamesMenu, 0x0019FDD0");
__asm__(".equ OnCardSwitch__9NamesMenu, 0x0019F9D8");
__asm__(".equ Reset__9HelpbarFE, 0x001BD920");
__asm__(".equ ChangeBtn__9HelpbarFEibG7stringx, 0x001BDB10");
__asm__(".equ Reformat__9HelpbarFE, 0x001BDA48");

void NamesMenu::OnActivate()
{
    TurnPQ(true);
    type = sl_parent->cur_type;
    save = (type == SaveLoadFrontEnd::SL_SAVE);
    FEMenuEntry* before = highlighted;
    FEMultiMenu::OnActivate();
    draw_message = false;

    if(before)
    {
        setHigh(before);
        adjusted_active_card = before->entry_num - num;
        active_card = NamesMenu::FindActive(adjusted_active_card);
        CheckCardNum(active_card);
        GetFileList(active_card, adjusted_active_card);
    }
    else
    {
        for(int i=LOWEST_CARD; i<HIGHEST_CARD; i++)
        {
            CheckCardNum(i);
            int adjust = NamesMenu::FindAdjusted(i);
            GetFileList(i, adjust);
        }
        SetActiveCard();

        FEMenuEntry* tmp = entry[NamesMenu::FindAdjusted(active_card)+num];
        setHigh(tmp);
    }

    OnCardSwitch();
    UpdateMessage();
    SetSecondaryCursor(entry[0]);
    first_vis_entry = secondary_cursor;
    last_vis_entry = entry[9];
    highlighted->SetSpecialColor(frontendmanager.col_highlight, frontendmanager.col_highlight2);

    if(sl_parent->in_frontend)
    {
        manager->helpbar->Reset();
        manager->helpbar->AddArrowH(ksGlobalTextArray[GT_FE_MENU_SWITCH]);
        manager->helpbar->AddArrowV();
        manager->helpbar->Reformat();
    }
}
